{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Indole-3-carbinol has poor oral bioavailability in humans due to GI instability and first-pass metabolism; with the highest assay-transfer score, this directly supports a low F (<20%) prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Salbutamol, which shares the query's salbutamol core, has absolute oral bioavailability of 44% in healthy volunteers, supporting F>=20%; however, the query's large N-substituent is a major difference.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Bambuterol, a beta-agonist with a modified N-substituent, has oral bioavailability ~10% in healthy adults, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Epanolol, a beta-blocker with a similar beta-amino alcohol and extended N-substituent, has absolute oral bioavailability ~7% in volunteers, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Phenylephrine, a phenolic beta-agonist, has poor oral bioavailability in healthy volunteers, supporting low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a salbutamol-like beta-agonist with a long lipophilic PEG-dichlorobenzyl N-substituent. Although salbutamol itself has ~44-50% oral bioavailability, the majority of high-transfer analogues with similar beta-amino alcohol/phenolic scaffolds and modified or extended N-substituents (bambuterol, epanolol, phenylephrine) show F <20%. The long flexible tail, high rotatable bond count, and very low neutral fraction at pH 7.4 favor incomplete absorption and extensive first-pass metabolism. Thus low F (<20%) is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for the exact query molecule.",
    "No data on metabolic stability of the long N-substituent or whether the compound acts as a prodrug.",
    "No permeability or efflux data; salbutamol's high F creates residual uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

